// test_dependency_extraction.rs - Test suite for dependency path extraction
// Generated by step4_bootstrap - Dependency Path Extraction

use split_decls_genesis::{
    mkdeps_paths, mkfull_dep_tree, get_rustc_dependencies, 
    extract_cargo_dependencies, DependencyPath
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing dependency path extraction...");
    
    // Test rustc dependency extraction
    println!("\n🦀 Testing rustc dependencies:");
    let rustc_deps = mkfull_dep_tree!("rustc");
    println!("✅ Found {} rustc dependencies", rustc_deps.len());
    
    // Test current project dependencies
    println!("\n📦 Testing current project dependencies:");
    if let Ok(current_deps) = extract_cargo_dependencies("./Cargo.toml") {
        println!("🔍 Current project dependencies:");
        for dep in &current_deps {
            println!("  📦 {} v{} → {} ({})", dep.name, dep.version, dep.path, dep.source);
        }
        println!("✅ Found {} current project dependencies", current_deps.len());
    }
    
    // Test macro-based extraction for various binaries
    println!("\n🔧 Testing macro-based extraction:");
    let binaries = vec!["rustc", "cargo", "clippy"];
    
    for binary in binaries {
        println!("\n🎯 Dependencies for {}:", binary);
        let deps = mkdeps_paths!(binary);
        println!("  📊 Total dependencies: {}", deps.len());
        
        // Show dependency sources breakdown
        let mut sources = std::collections::HashMap::new();
        for dep in &deps {
            *sources.entry(&dep.source).or_insert(0) += 1;
        }
        
        for (source, count) in sources {
            println!("  📍 {}: {} deps", source, count);
        }
    }
    
    println!("\n🎉 Dependency path extraction test complete!");
    Ok(())
}
